const GLOWUP = [
  {id:'cg-bursary', sub:'c-eq-harksen2', title:'The age limit',
   problem:'A provincial regulation offers state bursaries only to applicants under 30. Z, aged 35, meets every other criterion and is refused. The province says older applicants are a worse investment. Z wants the regulation declared invalid. Advise Z.',
   primer:{prompt:'Issue: choose the legal issue.', opts:['Whether the regulation unfairly discriminates against Z on the ground of age, contrary to s 9(3), and if so whether it is justified under s 36','Whether Z has a right to free higher education under s 29(1)(a)','Whether Z must bring a PEPUDA claim against the province','Whether the bursary is a valid structural interdict'], ans:0,
     why:'The facts raise differentiation on a listed ground (age) in legislation Z wants invalidated.', whyWrong:'Z attacks a regulation and wants it invalidated, so the issue is s 9(3) and s 36, not PEPUDA or basic education.'},
   foundation:{prompt:'Rule: choose the rules that apply.', opts:[{t:'Differentiation on a listed ground establishes discrimination, presumed unfair (s 9(5))',ok:true},{t:'Fairness factors: complainant’s position, purpose, impact on dignity (Hugo)',ok:true},{t:'Unfair discrimination may in principle be justified under s 36',ok:true},{t:'Mere differentiation needs only a rational link (Prinsloo)',ok:false}]},
   concealer:{prompt:'Exceptions & weaknesses: which points must your answer deal with?', opts:[{t:'The province’s purpose and whether it rebuts the presumption',ok:true},{t:'Legislation can only be invalidated by direct reliance on the Constitution, not PEPUDA',ok:true},{t:'Whether this is a s 9(2) remedial measure for the disadvantaged',ok:false}]},
   contour:{prompt:'Analysis: put the steps in order.', items:['There is differentiation between applicants under and over 30','It is on a listed ground (age): discrimination, presumed unfair','The province must rebut the presumption on the fairness factors','If unfair, ask whether it is justified under s 36'],
     why:'Follow the Harksen path.'},
   highlight:{prompt:'Authorities: choose what to cite.', opts:[{t:'Harksen v Lane',ok:true},{t:'President of the RSA v Hugo',ok:true},{t:'Constitution ss 9(3), 9(5) and 36',ok:true},{t:'Soobramoney',ok:false},{t:'Christian Education SA',ok:false}]},
   model:'ISSUE: Whether the regulation limiting bursaries to applicants under 30 unfairly discriminates against Z on the ground of age (s 9(3)), and if so whether the limitation is justified under s 36.\n\nRULE: Under the Harksen test, differentiation on a listed ground establishes discrimination, which is presumed unfair unless the discriminator establishes that it is fair (s 9(5)). Fairness focuses on impact, applying cumulatively the complainant’s position in society and past patterns of discrimination, the nature and purpose of the measure, and the extent to which rights and fundamental dignity are impaired (Hugo). Unfair discrimination limits s 9(3) and may in principle be justified under s 36, though there is conceptual difficulty in calling unfairness reasonable and justifiable. Because Z wants a regulation invalidated, Z must rely directly on the Constitution; PEPUDA cannot invalidate legislation.\n\nAPPLICATION: The regulation differentiates between applicants under and over 30. Age is a listed ground, so discrimination is established and presumed unfair. The province must rebut the presumption: it relies on a purpose (return on investment), but must also address Z’s position and the impact on Z’s rights and dignity. If it cannot rebut the presumption, the discrimination is unfair and the province must justify it under s 36 (law of general application, then the s 36(1) factors).\n\nCONCLUSION: Z has a strong claim: discrimination is presumed unfair and the onus is on the province. Unless it proves fairness or a s 36 justification, the regulation should be declared invalid to the extent of the inconsistency (s 172(1)(a)).',
   rubric:['Identifies the listed ground and the Harksen path','States the s 9(5) presumption and onus','Applies the three fairness factors (Hugo)','Mentions s 36 justification','Notes the direct-reliance route (not PEPUDA) for legislation','Clear conclusion and remedy'],
   source:EQ('6, 7')},
];

